'use strict';
// Shared curriculum stays in static hosting. Only intentional learner changes are saved.
let msData=null,msPending=null,msEpoch=0,msError='';
let msRoute={view:'areas',area:'',lesson:'',query:'',mode:'study',mistakes:false};
function msValidate(data){if(data?.id!=='toolbox-maritime-study'||!Array.isArray(data.areas)||!Array.isArray(data.lessons)||!data.lessons.length)throw Error('The maritime study file is incomplete.');const ids=new Set();for(const l of data.lessons){if(ids.has(l.id)||!data.areas.some(a=>a.id===l.area)||!l.notes?.length||!l.questions?.length||!l.references.every(r=>data.references[r]))throw Error('The maritime study file has an invalid lesson.');ids.add(l.id);for(const q of l.questions){if(ids.has(q.id)||!q.stem||!q.explanation||q.options?.length<2||!Number.isInteger(q.answer)||q.answer<0||q.answer>=q.options.length)throw Error('The maritime study file has an invalid question.');ids.add(q.id)}}return data}
async function msLoad(){if(msData)return msData;if(msPending)return msPending;msPending=(async()=>{try{const r=await fetch('assets/learning/maritime-study.json?v=20261021-1',{cache:'force-cache'});if(!r.ok)throw Error('Maritime Study could not load. Check your connection and retry.');msData=msValidate(await r.json());return msData}finally{msPending=null}})();return msPending}
async function msOpen(){const owner=cloudUser?.id||'local',epoch=++msEpoch;msRoute={view:'areas',area:'',lesson:'',query:'',mode:'study',mistakes:false};msError='';page='review';lhScreen='maritime';reviewReadSet=null;render();try{await msLoad();if(epoch===msEpoch&&page==='review'&&lhScreen==='maritime'&&owner===(cloudUser?.id||'local'))render()}catch(e){if(epoch===msEpoch&&page==='review'&&lhScreen==='maritime'&&owner===(cloudUser?.id||'local')){msError=e.message;render()}}}
function msProgress(){return learningData().maritimeStudy||{read:{},answers:{}}}
function msLesson(){return msData?.lessons.find(l=>l.id===msRoute.lesson)}
function msAnswer(q){return msProgress().answers?.[q.id]}
function msWrong(l){return l.questions.some(q=>{const row=msAnswer(q);return row&&row.choice!==q.answer})}
function msMatches(l){const words=msRoute.query.toLowerCase().trim().split(/\s+/).filter(Boolean),hay=[l.id,l.title,l.category,l.goal,...l.notes,...l.questions.flatMap(q=>[q.stem,...q.options,q.explanation])].join(' ').toLowerCase();return words.every(w=>hay.includes(w))}
function msStatus(text){const n=document.getElementById('msStatus');if(n)n.textContent=text}
function msMarkRead(){const l=msLesson();if(!l||!lhSpeakingCanSave())return false;if(msProgress().read?.[l.id])return true;const ok=learningSave(d=>{d.maritimeStudy||={read:{},answers:{}};d.maritimeStudy.read||={};d.maritimeStudy.read[l.id]=new Date().toISOString()});if(ok)render();else msStatus(learningMessage);return ok}
function msChoose(id,choice){const l=msLesson(),q=l?.questions.find(q=>q.id===id);if(msRoute.mode!=='practice'||!q||!Number.isInteger(choice)||choice<0||choice>=q.options.length||!lhSpeakingCanSave())return false;if(msAnswer(q)?.choice===choice)return true;const ok=learningSave(d=>{d.maritimeStudy||={read:{},answers:{}};d.maritimeStudy.answers||={};d.maritimeStudy.answers[id]={choice,date:new Date().toISOString()}});if(ok)render();else msStatus(learningMessage);return ok}
function msHead(title,back='areas',description=''){return `<header class="learning-heading"><div><button class="text-button" data-ms="${back}">← ${back==='study'?'Study':back==='areas'?'Maritime Study':'Topics'}</button><h1>${esc(title)}</h1>${description?`<p class="hint">${esc(description)}</p>`:''}</div></header>`}
function msSearch(){return `<label class="search">${icon('search')}<input id="msSearch" type="search" placeholder="Search lessons, questions or answers" aria-label="Search Maritime Study" value="${esc(msRoute.query)}"></label>`}
function msCards(){const list=msData.lessons.filter(l=>(!msRoute.area||l.area===msRoute.area)&&(!msRoute.mistakes||msWrong(l))&&msMatches(l));return `<p class="hint" role="status">${list.length} matching lessons</p><div class="lh-topic-grid">${list.map(l=>`<button class="card lh-topic" data-ms-lesson="${esc(l.id)}"><span class="lh-module-code">${esc(l.category)} · ${esc(l.id)}</span><strong>${esc(l.title)}</strong><small>${l.questions.length} practice questions${msProgress().read?.[l.id]?' · Read ✓':''}${msWrong(l)?' · Revisit answers':''}</small></button>`).join('')||'<p>No matching lessons. Try another word or turn off mistake review.</p>'}</div>`}
function msWireSearch(){const n=document.getElementById('msSearch');if(n)n.oninput=e=>{msRoute.query=e.target.value;document.getElementById('msCards').innerHTML=msCards();const current=hubRouteHistory.at(-1);if(current?.maritime)current.maritime={...msRoute}}}
function msQuestionCards(l){return l.questions.map((q,i)=>{const row=msAnswer(q),reveal=msRoute.mode==='study'||!!row,correct=row?.choice===q.answer;return `<article class="card ms-question"><small>QUESTION ${i+1} · ${esc(q.id)}</small><h2>${esc(q.stem)}</h2>${msRoute.mode==='practice'?`<div class="review-options">${q.options.map((option,j)=>`<button class="review-option ${row?.choice===j?'selected':''} ${reveal&&j===q.answer?'correct':''}" data-ms-question="${esc(q.id)}" data-ms-choice="${j}" aria-pressed="${row?.choice===j}"><b>${String.fromCharCode(65+j)}</b><span>${esc(option)}</span></button>`).join('')}</div>`:''}${reveal?`<div class="lh-direct-answer"><strong>${msRoute.mode==='practice'?(correct?'Correct':'Review this answer'):'Answer'}: ${esc(q.options[q.answer])}</strong><p>${esc(q.explanation)}</p></div>`:'<p class="hint">Choose an answer to see the explanation.</p>'}</article>`}).join('')}
function msRender(){if(!msData){app.innerHTML=msHead('Toolbox Maritime Study','study')+`<section class="card"><p role="status">${esc(msError||'Loading the study library…')}</p>${msError?'<button class="btn" data-ms="retry">Retry loading</button>':''}</section>`;return}const count=msData.lessons.length,total=msData.lessons.reduce((n,l)=>n+l.questions.length,0);if(msRoute.view==='lesson'){const l=msLesson();if(!l){msRoute.view='topics';msRender();return}const read=!!msProgress().read?.[l.id];app.innerHTML=msHead(l.title,'topics',l.category+' · '+l.id)+`<p class="ms-notice">${esc(msData.notice)}</p><article class="card ms-notes"><span class="lh-level">LEARNING GOAL</span><h2>${esc(l.goal)}</h2>${l.notes.map(p=>`<p>${esc(p)}</p>`).join('')}<div class="ms-scenario"><strong>Think it through</strong><p>${esc(l.scenario)}</p></div><p><strong>Remember:</strong> ${esc(l.takeaway)}</p><button class="btn quiet" data-ms="read" ${read?'disabled':''}>${read?'Marked as read ✓':'Mark as read'}</button><small class="hint">Reading progress is self-reported.</small></article><div class="lh-mode-switch" role="group" aria-label="Question mode"><button data-ms-mode="study" aria-pressed="${msRoute.mode==='study'}" class="${msRoute.mode==='study'?'selected':''}">Study answers</button><button data-ms-mode="practice" aria-pressed="${msRoute.mode==='practice'}" class="${msRoute.mode==='practice'?'selected':''}">Practise</button></div><p id="msStatus" role="status" class="hint"></p>${msQuestionCards(l)}<details class="card ms-references"><summary>References and content status</summary><p>Original introductory content. Independent technical review is pending. Source pages support the background; they are not an endorsement of these questions.</p>${l.references.map(id=>{const r=msData.references[id];return `<p><a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.title)} ↗</a><br><small>${esc(r.section)}</small></p>`}).join('')}<small>Reference check: ${esc(msData.referenceChecked)} · Revision ${esc(msData.version)}</small></details>`;return}if(msRoute.view==='areas'){app.innerHTML=msHead('Toolbox Maritime Study','study','Build knowledge for your department and vessel.')+`<p class="ms-notice">Introductory edition · ${count} lessons · ${total} original questions · educator review pending.</p><div class="lh-choice-grid">${msData.areas.map(a=>`<button class="card lh-choice" data-ms-area="${esc(a.id)}"><span class="lh-symbol">${lhIcon('study')}</span><h2>${esc(a.title)}</h2><p>${esc(a.description)}</p><b>${msData.lessons.filter(l=>l.area===a.id).length} lessons →</b></button>`).join('')}</div>`+msSearch()+`<div class="ms-controls"><button class="text-button" data-ms="mistakes" aria-pressed="${msRoute.mistakes}">${msRoute.mistakes?'Show all lessons':'Review mistakes'}</button><small class="hint">${msData.lessons.filter(l=>msProgress().read?.[l.id]).length}/${count} marked as read</small></div><div id="msCards">${msCards()}</div>`;msWireSearch();return}const area=msData.areas.find(a=>a.id===msRoute.area);app.innerHTML=msHead(area?.title||'All topics','areas',area?.description||'')+msSearch()+`<div class="ms-controls"><button class="text-button" data-ms="mistakes" aria-pressed="${msRoute.mistakes}">${msRoute.mistakes?'Show all lessons':'Review mistakes'}</button></div><div id="msCards">${msCards()}</div>`;msWireSearch()}
const msOldStudyLanding=lhStudyLanding;lhStudyLanding=function(){msOldStudyLanding();app.querySelector('.lh-choice-grid')?.insertAdjacentHTML('afterbegin',`<button class="card lh-choice" data-ms="open"><span class="lh-symbol">${lhIcon('study')}</span><h2>Toolbox Maritime Study</h2><p>Shared fundamentals, Deck, Engine and eight vessel specializations.</p><b>Explore lessons & practice →</b></button>`)};
const msOldReviewView=reviewView;reviewView=function(){if(lhScreen==='maritime'&&reviewReadSet===null)msRender();else msOldReviewView()};
document.addEventListener('click',e=>{const b=e.target.closest?.('button');if(!b||b.disabled||!Object.keys(b.dataset).some(k=>k.startsWith('ms')))return;e.stopImmediatePropagation();const d=b.dataset;if(d.ms==='open'||d.ms==='retry'){msOpen();return}if(page!=='review'||lhScreen!=='maritime'||!msData)return;if(d.msArea){if(!msData.areas.some(a=>a.id===d.msArea))return;msRoute={view:'topics',area:d.msArea,lesson:'',query:'',mode:'study',mistakes:false}}else if(d.msLesson){if(!msData.lessons.some(l=>l.id===d.msLesson))return;msRoute.view='lesson';msRoute.lesson=d.msLesson;msRoute.mode='study'}else if(d.msMode){if(!['study','practice'].includes(d.msMode))return;msRoute.mode=d.msMode}else if(d.msQuestion){msChoose(d.msQuestion,Number(d.msChoice));return}else if(d.ms==='read'){msMarkRead();return}else if(d.ms==='study'){lhGo('study');return}else if(d.ms==='areas'){msRoute={view:'areas',area:'',lesson:'',query:'',mode:'study',mistakes:false}}else if(d.ms==='topics'){msRoute.view='topics'}else if(d.ms==='mistakes'){msRoute.mistakes=!msRoute.mistakes}else return;render();window.scrollTo(0,0)},true);
const msOldSnapshot=hubRouteSnapshot,msOldRouteKey=hubRouteKey,msOldBack=hubBack;
hubRouteSnapshot=function(){return {...msOldSnapshot(),maritime:lhScreen==='maritime'?{...msRoute}:null}};
hubRouteKey=function(r){return msOldRouteKey(r)+(r.page==='review'&&r.maritime?JSON.stringify(r.maritime):'')};
hubBack=function(){const prev=hubRouteHistory.at(-2)?.maritime;if(prev){msEpoch++;msRoute={...prev}}return msOldBack()};
let msOwner=cloudUser?.id||'local';const msOldRender=render;render=function(){const owner=cloudUser?.id||'local';if(owner!==msOwner){msOwner=owner;msEpoch++;msRoute={view:'areas',area:'',lesson:'',query:'',mode:'study',mistakes:false};msError=''}msOldRender()};
hubQuickGuides.review[1].push('Toolbox Maritime Study has original introductory lessons across departments and vessel types. Search lessons and questions, practise with explanations, and revisit mistakes. Independent educator review is pending.');
render();
